<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Auth extends MY_Controller { public function __construct(){parent::__construct();$this->load->model('User_model');}
 public function login(){ if($this->session->userdata('user_id')) redirect('/'); if($this->input->method()==='post'){ $login=trim($this->input->post('login',true));$password=$this->input->post('password');$u=$this->User_model->find_by_login($login); if($u && password_verify($password,$u->password_hash)){ $this->session->set_userdata(array('user_id'=>$u->id,'username'=>$u->username,'role'=>$u->role)); redirect($u->role==='admin'?'admin':'/'); } $data['error']='Invalid username/email or password.'; } $this->view('auth/login',isset($data)?$data:array()); }
 public function register(){ if($this->input->method()==='post'){ $this->form_validation->set_rules('name','Name','required|trim');$this->form_validation->set_rules('username','Username','required|alpha_numeric|min_length[3]|is_unique[users.username]');$this->form_validation->set_rules('email','Email','required|valid_email|is_unique[users.email]');$this->form_validation->set_rules('password','Password','required|min_length[6]'); if($this->form_validation->run()){ $id=$this->User_model->create(array('name'=>$this->input->post('name',true),'username'=>$this->input->post('username',true),'email'=>$this->input->post('email',true),'password_hash'=>password_hash($this->input->post('password'),PASSWORD_DEFAULT),'role'=>'customer')); $this->session->set_userdata(array('user_id'=>$id,'username'=>$this->input->post('username',true),'role'=>'customer')); redirect('/'); } } $this->view('auth/register'); }
 public function logout(){ $this->session->sess_destroy(); redirect('/'); }
}
